  this->state.currentPrimitive->slots[0].distance = 1.0f;
  this->state.currentPrimitive->slots[0].alphaB = 0;
  this->state.currentPrimitive->slots[0].vecBPre.x = 0.0f;
  this->state.currentPrimitive->slots[0].vecBPre.z = 0.0f;
