    for (int i = 0; i < 21; ++i) {
      this->state.currentPrimitive->slots[0].height[i] = 0.0f;
      this->state.currentPrimitive->slots[0].flag1[i] = 0;
    }

    this->state.currentPrimitive->slots[1].life = 1;
