      this->state.lastPrim->state.slots[i].height[1] = 0.0f;
      this->state.lastPrim->state.slots[i].height[2] = static_cast<float>(std::max(rand() % 40, 0)) * 0.01f + 0.4f;
      this->state.lastPrim->state.slots[i].fullDisplayAngle = 0;
